-- Caller wraps this fixture in BEGIN/ROLLBACK; no source data is retained or removed.
DO $$
DECLARE native uuid;actor uuid;prof uuid;rep2 uuid;org uuid;sid uuid:=gen_random_uuid();wid uuid:=gen_random_uuid();sh uuid;sh2 uuid;entry uuid;r jsonb;r2 jsonb;payload jsonb;offered timestamptz;before_n int;mem uuid;store2 uuid:=gen_random_uuid();manual uuid:=gen_random_uuid();ownermem uuid;
BEGIN
 SELECT im.target_user_id,im.source_user_id,p.id,m.organization_id INTO native,actor,prof,org FROM tj.source_user_identity_map im JOIN tj.profiles p ON p.user_id=im.source_user_id JOIN tj.organization_members m ON m.user_id=im.source_user_id JOIN tj.organizations o ON o.id=m.organization_id WHERE im.activation_status='activated' AND m.status='active' AND m.role='owner' AND o.status='active' AND o.deleted_at IS NULL LIMIT 1;
 SELECT p.id INTO rep2 FROM tj.profiles p JOIN tj.organization_members m ON m.user_id=p.user_id WHERE m.organization_id=org AND m.status='active' AND m.role IN('owner','admin','manager','member') AND p.id<>prof LIMIT 1;
 IF rep2 IS NULL THEN RAISE EXCEPTION 'fixture_unavailable';END IF;
 PERFORM set_config('request.jwt.claim.sub',native::text,true);
 INSERT INTO tj.org_locations(id,organization_id,location_type,name,timezone) VALUES(sid,org,'store','Rollback UP Rotation Store','America/Toronto');
 -- Isolate both reps from retained floor shifts inside this rollback transaction.
 UPDATE tj.iq_shift_records SET is_active=false WHERE organization_id=org AND user_id IN(prof,rep2) AND is_active;
 payload:=jsonb_build_object('organization_id',org,'store_id',sid);
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF NOT EXISTS(SELECT 1 FROM tj.profiles WHERE user_id=actor AND id=prof) THEN RAISE EXCEPTION 'boot identity inaccessible';END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','clock_in','rep_profile_id',prof,'role','salesperson'));
 EXECUTE 'RESET ROLE';
 IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'clock in: %',r;END IF;sh:=(r->>'shift_id')::uuid;
 r2:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','clock_in','rep_profile_id',prof));IF r2->>'shift_id'<>sh::text OR r2->>'changed'<>'false' THEN RAISE EXCEPTION 'duplicate shift';END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','clock_in','rep_profile_id',rep2));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'second shift: %',r;END IF;sh2:=(r->>'shift_id')::uuid;
 IF (SELECT count(*) FROM tj.iq_up_queue_entries WHERE store_id=sid AND is_current_up)<>1 OR (SELECT count(*) FROM tj.iq_up_queue_entries WHERE store_id=sid AND is_next_in_line)<>1 THEN RAISE EXCEPTION 'queue flag failure';END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','status','rep_profile_id',prof,'status','break'));
 IF r->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.iq_up_queue_entries WHERE store_id=sid AND user_id=rep2 AND is_current_up) THEN RAISE EXCEPTION 'unavailable rep not skipped: %',r;END IF;
 SELECT id INTO entry FROM tj.iq_up_queue_entries WHERE store_id=sid AND is_current_up;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','accept_up','entry_id',entry));r2:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','recalc'));
 IF EXISTS(SELECT 1 FROM tj.iq_up_queue_entries WHERE id=entry AND up_offered_at IS NOT NULL) THEN RAISE EXCEPTION 'accepted offer reset';END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','status','rep_profile_id',prof,'status','available'));
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','bump','rep_profile_id',prof));
 SELECT id,up_offered_at INTO entry,offered FROM tj.iq_up_queue_entries WHERE store_id=sid AND is_current_up;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','timeout','entry_id',entry,'expected_offered_at',offered));IF r->>'changed'<>'false' THEN RAISE EXCEPTION 'early timeout';END IF;
 offered:=now()-interval '2 minutes';UPDATE tj.iq_up_queue_entries SET up_offered_at=offered WHERE id=entry;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','timeout','entry_id',entry,'expected_offered_at',offered));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'timeout: %',r;END IF;
 r2:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','timeout','entry_id',entry,'expected_offered_at',offered));
 IF (SELECT ups_missed FROM tj.iq_shift_records WHERE id=sh)<>1 OR (SELECT count(*) FROM tj.iq_missed_and_potential_missed_ups WHERE store_id=sid)<>1 THEN RAISE EXCEPTION 'duplicate timeout metrics';END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','profiles'));IF r->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(r->'profiles') p WHERE p->>'id'=prof::text) THEN RAISE EXCEPTION 'profile picker mapping';END IF;
 payload:=payload||jsonb_build_object('waiting_id',wid,'action','log','waiting',jsonb_build_object('store_id',sid,'customer_display_name','Rollback Rotation Customer'),'products','[]'::jsonb);
 r:=public.tj_runtime_up_crm_handoff(payload);IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'log: %',r;END IF;
 r2:=public.tj_runtime_up_crm_handoff(payload||jsonb_build_object('action','assign','rep_profile_id',prof));IF r2->>'ok'<>'true' THEN RAISE EXCEPTION 'assign: %',r2;END IF;
 IF EXISTS(SELECT 1 FROM tj.iq_up_queue_entries WHERE store_id=sid AND user_id=prof AND is_current_up) THEN RAISE EXCEPTION 'busy rep offered UP';END IF;
 r2:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','clock_out','rep_profile_id',prof));IF r2->>'error'<>'end_or_reassign_visit_first' THEN RAISE EXCEPTION 'clocked out active visit';END IF;
 r2:=public.tj_runtime_up_crm_handoff(payload||jsonb_build_object('action','assign','rep_profile_id',rep2,'counts_as_up',false,'reason','Specialist handoff'));IF r2->>'ok'<>'true' THEN RAISE EXCEPTION 'reassign: %',r2;END IF;
 IF NOT EXISTS(SELECT 1 FROM tj.iq_up_queue_entries WHERE store_id=sid AND user_id=prof AND status_code='available' AND is_available_for_assignment) OR NOT EXISTS(SELECT 1 FROM tj.crm_deals d JOIN tj.profiles p ON p.user_id=d.owner_user_id WHERE d.id=(r->>'deal_id')::uuid AND p.id=rep2) THEN RAISE EXCEPTION 'reassignment floor / CRM ownership';END IF;
 r2:=public.tj_runtime_up_crm_handoff(payload||jsonb_build_object('action','after_sale','closed',true));IF r2->>'ok'<>'true' THEN RAISE EXCEPTION 'end visit: %',r2;END IF;
 r2:=public.tj_runtime_up_crm_handoff(payload||jsonb_build_object('action','after_sale','closed',true));
 IF (SELECT closed_sales FROM tj.iq_shift_records WHERE id=sh2)<>1 OR EXISTS(SELECT 1 FROM tj.iq_customer_interactions WHERE customer_waiting_id=wid AND ended_at IS NULL) OR NOT EXISTS(SELECT 1 FROM tj.iq_customer_waiting_queue WHERE id=wid AND status='completed') THEN RAISE EXCEPTION 'end visit not terminal / idempotent';END IF;
 IF NOT EXISTS(SELECT 1 FROM tj.iq_up_queue_entries WHERE store_id=sid AND user_id=rep2 AND status_code='available') THEN RAISE EXCEPTION 'completed rep not released';END IF;
 payload:=jsonb_build_object('organization_id',org,'store_id',sid);
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','greeter_start','rep_profile_id',prof));r2:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','greeter_end','rep_profile_id',prof));IF r->>'ok'<>'true' OR r2->>'ok'<>'true' THEN RAISE EXCEPTION 'greeter: % %',r,r2;END IF;
 -- A non-sale closes the floor visit while keeping the CRM follow-up and unknown value.
 wid:=gen_random_uuid();
 r:=public.tj_runtime_up_crm_handoff(payload||jsonb_build_object('action','log','waiting_id',wid,'waiting',jsonb_build_object('store_id',sid,'customer_display_name','Rollback Follow-up Customer'),'products','[]'::jsonb));
 r2:=public.tj_runtime_up_crm_handoff(payload||jsonb_build_object('action','assign','waiting_id',wid,'rep_profile_id',prof));
 IF r->>'ok'<>'true' OR r2->>'ok'<>'true' THEN RAISE EXCEPTION 'follow-up fixture failed';END IF;
 r2:=public.tj_runtime_up_crm_handoff(payload||jsonb_build_object('action','after_sale','waiting_id',wid,'closed',false,'reason','comparing_options','follow_up_date','2026-10-12','no_follow_up',false));
 IF r2->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.crm_deals WHERE id=(r->>'deal_id')::uuid AND closed_at IS NULL AND value_amount IS NULL AND next_action_date='2026-10-12'::date AND follow_up_status='scheduled') OR NOT EXISTS(SELECT 1 FROM tj.iq_customer_interactions WHERE customer_waiting_id=wid AND outcome='no_sale' AND ended_at IS NOT NULL AND follow_up_date='2026-10-12'::date AND sale_amount IS NULL) OR (SELECT closed_sales FROM tj.iq_shift_records WHERE id=sh)<>0 THEN RAISE EXCEPTION 'non-sale follow-up / pricing evidence failed: %',r2;END IF;

 IF NOT EXISTS(SELECT 1 FROM tj.metric_snapshots WHERE location_id=sid AND metric_key='floor_conversion' AND actual_value=50) THEN RAISE EXCEPTION 'automatic reporting trigger did not publish';END IF;
 UPDATE tj.metric_snapshots SET target_value=10 WHERE location_id=sid AND metric_key='floor_conversion';
 UPDATE tj.iq_hourly_traffic_summaries SET adjusted_traffic=9 WHERE store_id=sid AND raw_traffic=2;
 r:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','refresh_reports'));
 IF r->>'ok'<>'true' OR (r->>'walk_ins')::int<>2 OR (r->>'closed_visits')::int<>1 OR NOT EXISTS(SELECT 1 FROM tj.metric_snapshots WHERE location_id=sid AND metric_key='floor_conversion' AND actual_value=50) THEN RAISE EXCEPTION 'distinct visit report failed: %',r;END IF;
 IF r->>'period_key'<>((now() AT TIME ZONE 'America/Toronto')::date)::text OR NOT EXISTS(SELECT 1 FROM tj.metric_snapshots WHERE location_id=sid AND metric_key='floor_conversion' AND target_value=10 AND variance_value=40) OR NOT EXISTS(SELECT 1 FROM tj.iq_hourly_traffic_summaries WHERE store_id=sid AND raw_traffic=2 AND adjusted_traffic=9) THEN RAISE EXCEPTION 'local date, target or traffic adjustment preservation';END IF;
 r:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','save_settings','settings',jsonb_build_object('queue_name','Fixture Floor','missed_up_queue_rule','back_of_queue','break_max_per_shift',2,'paid_break_minutes',15,'lunch_minutes',30,'is_open_rotation_enabled',false,'accept_up_timeout_seconds',45,'accept_up_action','back_of_queue','greeter_enabled',true,'greeter_user_id',prof)));
 IF r->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.iq_store_settings WHERE store_id=sid AND accept_up_timeout_seconds=45 AND greeter_user_id=prof) OR EXISTS(SELECT 1 FROM tj.iq_up_queue_entries WHERE store_id=sid AND user_id=prof AND is_in_queue) THEN RAISE EXCEPTION 'settings greeter save failed: %',r;END IF;
 r:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','save_settings','settings',jsonb_build_object('queue_name','Fixture Floor','missed_up_queue_rule','skip_once','break_max_per_shift',2,'paid_break_minutes',15,'lunch_minutes',30,'is_open_rotation_enabled',true,'accept_up_timeout_seconds',30,'accept_up_action','next_in_line','greeter_enabled',false)));
 IF r->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.iq_up_queue_entries WHERE store_id=sid AND user_id=prof AND is_in_queue) THEN RAISE EXCEPTION 'greeter release failed: %',r;END IF;
 r:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','save_settings','settings',jsonb_build_object('accept_up_timeout_seconds',0)));
 IF r->>'ok'='true' OR NOT EXISTS(SELECT 1 FROM tj.iq_store_settings WHERE store_id=sid AND accept_up_timeout_seconds=30) THEN RAISE EXCEPTION 'invalid settings not atomic';END IF;
 wid:=gen_random_uuid();
 EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','file_dispute','dispute_id',wid,'affected_profile_id',rep2,'reason','Rollback dispute'));
 EXECUTE 'RESET ROLE';
 r2:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','file_dispute','dispute_id',wid,'affected_profile_id',rep2,'reason','Rollback dispute'));
 IF r->>'ok'<>'true' OR r2->>'changed'<>'false' OR (SELECT count(*) FROM tj.iq_up_disputes WHERE id=wid)<>1 THEN RAISE EXCEPTION 'dispute retry failed: % %',r,r2;END IF;
 r:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','resolve_dispute','dispute_id',wid,'decision','upheld','notes','Fixture resolution','restore_queue_priority',true));
 IF r->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.iq_up_disputes WHERE id=wid AND status='resolved' AND manager_id=prof AND queue_snapshot_after IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM tj.iq_up_queue_entries WHERE store_id=sid AND user_id=rep2 AND is_current_up) THEN RAISE EXCEPTION 'dispute correction failed: %',r;END IF;
 r:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','resolve_dispute','dispute_id',wid,'decision','dismissed','restore_queue_priority',false));IF r->>'changed'<>'false' THEN RAISE EXCEPTION 'resolved dispute retried';END IF;

 SELECT id INTO mem FROM tj.organization_members WHERE organization_id=org AND user_id=(SELECT user_id FROM tj.profiles WHERE id=rep2);
 SELECT id INTO ownermem FROM tj.organization_members WHERE organization_id=org AND user_id=actor;

 r:=public.tj_runtime_create_org_invite(org,(SELECT email FROM auth.users WHERE id=native),'member',NULL,sid,NULL);
 IF r->>'invite_code' IS NULL THEN RAISE EXCEPTION 'authorized invite create failed';END IF;
 r2:=public.tj_runtime_accept_org_invite(r->>'invite_code');
 IF r2->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.organization_members WHERE id=ownermem AND role='owner' AND status='active') THEN RAISE EXCEPTION 'invite acceptance changed existing owner';END IF;
 r:=public.tj_runtime_create_org_invite(org,'rollback-invite@example.test','member',NULL,sid,NULL);
 r2:=public.tj_runtime_revoke_org_invite((r->>'id')::uuid);IF r2->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.org_invites WHERE id=(r->>'id')::uuid AND status='revoked') THEN RAISE EXCEPTION 'invite revocation failed';END IF;
 SELECT ups_missed INTO before_n FROM tj.iq_shift_records WHERE id=sh;
 EXECUTE 'SET LOCAL ROLE authenticated';
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','report_missed','missed_id',manual,'rep_profile_id',prof,'reason','Rollback manual report'));
 EXECUTE 'RESET ROLE';
 r2:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','report_missed','missed_id',manual,'rep_profile_id',prof,'reason','Rollback manual report'));
 IF r->>'ok'<>'true' OR r2->>'changed'<>'false' OR (SELECT ups_missed FROM tj.iq_shift_records WHERE id=sh)<>before_n THEN RAISE EXCEPTION 'pending manual report penalized staff: %',r;END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','review_missed','missed_id',manual,'decision','confirm'));
 r2:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','review_missed','missed_id',manual,'decision','confirm'));
 IF r->>'ok'<>'true' OR r2->>'ok'<>'true' OR (SELECT ups_missed FROM tj.iq_shift_records WHERE id=sh)<>before_n+1 THEN RAISE EXCEPTION 'confirmed report double counted';END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','review_missed','missed_id',manual,'decision','excuse'));
 IF r->>'ok'<>'true' OR (SELECT ups_missed FROM tj.iq_shift_records WHERE id=sh)<>before_n THEN RAISE EXCEPTION 'excused metric not restored';END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','revoke_store','member_id',mem,'store_id',sid));IF r->>'error'<>'clock_out_member_first' THEN RAISE EXCEPTION 'revoked active shift';END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','deactivate_member','member_id',mem));IF r->>'error'<>'clock_out_member_first' THEN RAISE EXCEPTION 'active member deactivated';END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','clock_out','rep_profile_id',rep2));
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','deactivate_member','member_id',mem));IF r->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.organization_members WHERE id=mem AND status='suspended') THEN RAISE EXCEPTION 'member deactivation failed: %',r;END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','activate_member','member_id',mem));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'reactivation failed';END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','add_store','new_store_id',store2,'name','Rollback Administration Store','city','Fixture'));
 r2:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','add_store','new_store_id',store2,'name','Rollback Administration Store','city','Fixture'));IF r->>'ok'<>'true' OR (SELECT count(*) FROM tj.org_locations WHERE id=store2)<>1 THEN RAISE EXCEPTION 'store create retry failed';END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','assign_store','member_id',mem,'store_id',store2,'primary',true));IF r->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.org_location_members WHERE location_id=store2 AND user_id=(SELECT user_id FROM tj.profiles WHERE id=rep2) AND is_primary) THEN RAISE EXCEPTION 'source identity store grant failed';END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','deactivate_store','store_id',store2));IF r->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.org_locations WHERE id=store2 AND NOT is_active) THEN RAISE EXCEPTION 'store deactivation failed';END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','clock_in','store_id',store2,'rep_profile_id',rep2));IF r->>'ok'='true' THEN RAISE EXCEPTION 'archived store accepted clock in';END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','activate_store','store_id',store2));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'store restore failed';END IF;
 UPDATE tj.organization_members SET role='admin' WHERE organization_id=org AND role='owner' AND user_id<>actor;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','set_role','member_id',ownermem,'role','member'));IF r->>'error'<>'last_owner_required' THEN RAISE EXCEPTION 'last owner removed: %',r;END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','team_roster'));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'roster failed';END IF;
 UPDATE tj.organization_members SET role='member',visibility_scope='all' WHERE organization_id=org AND user_id=actor;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','set_role','member_id',mem,'role','owner'));IF r->>'error'<>'administrator_required' THEN RAISE EXCEPTION 'member escalated role';END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','review_missed','missed_id',manual,'decision','confirm'));IF r->>'error'<>'manager_required' THEN RAISE EXCEPTION 'member applied missed KPI';END IF;
 r:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','save_settings','settings','{}'::jsonb));IF r->>'error'<>'manager_required' THEN RAISE EXCEPTION 'member changed settings';END IF;
 r:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','resolve_dispute','dispute_id',wid,'decision','upheld'));IF r->>'error'<>'manager_required' THEN RAISE EXCEPTION 'member resolved dispute';END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','clock_out','rep_profile_id',rep2));IF r->>'error'<>'own_shift_required' THEN RAISE EXCEPTION 'member changed another shift: %',r;END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','bump','rep_profile_id',prof));IF r->>'error'<>'manager_required' THEN RAISE EXCEPTION 'member bumped queue';END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','clock_out','rep_profile_id',prof));IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'own clock out: %',r;END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','recalc','organization_id',gen_random_uuid()));IF r->>'ok'='true' THEN RAISE EXCEPTION 'foreign organization allowed';END IF;
 r:=public.tj_runtime_up_operations(payload||jsonb_build_object('action','refresh_reports','store_id',gen_random_uuid()));IF r->>'ok'='true' THEN RAISE EXCEPTION 'foreign store operations allowed';END IF;


 -- Caller has clocked out; source CRM location must still be the original UP store.
 IF NOT EXISTS(SELECT 1 FROM tj.crm_deals WHERE organization_id=org AND location_id=sid) THEN RAISE EXCEPTION 'CRM handoff lost explicit source store';END IF;
 -- Test self-revocation as an ordinary organization owner, without the platform-admin override.
 UPDATE tj.organization_members SET role='owner',visibility_scope='all' WHERE organization_id=org AND user_id=actor;
 UPDATE tj.platform_admins SET user_id=gen_random_uuid() WHERE user_id=actor;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','assign_store','member_id',ownermem,'store_id',sid,'primary',true));
 IF r->>'ok'<>'true' THEN RAISE EXCEPTION 'self store grant: %',r;END IF;
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','assign_store','member_id',ownermem,'store_id',store2));
 r:=tj_private.set_platform_context(org,sid);
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','revoke_store','member_id',ownermem,'store_id',sid));
 r2:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','revoke_store','member_id',ownermem,'store_id',sid));
 IF r->>'ok'<>'true' OR r2->>'ok'<>'true' OR NOT EXISTS(SELECT 1 FROM tj.org_location_members WHERE organization_id=org AND location_id=sid AND user_id=actor AND NOT is_active AND revoked_at IS NOT NULL AND revoked_by=actor) OR NOT EXISTS(SELECT 1 FROM tj.org_location_members WHERE location_id<>sid AND user_id=actor AND is_active AND is_primary) THEN RAISE EXCEPTION 'revocation/history/primary fallback: % %',r,r2;END IF;
 IF tj_private.aiq_store_allows(org,sid) OR NOT tj_private.aiq_store_allows(org,store2) OR EXISTS(SELECT 1 FROM tj_private.allowed_store_pairs() WHERE store_id=sid) OR EXISTS(SELECT 1 FROM tj_private.my_platform_locations(org) WHERE location_id=sid) OR tj_private.my_platform_context()->>'location_id'=sid::text THEN RAISE EXCEPTION 'revoked store escaped shared helpers';END IF;
 BEGIN PERFORM tj_private.set_platform_context(org,sid);RAISE EXCEPTION 'context accepted revoked store';EXCEPTION WHEN OTHERS THEN IF SQLERRM<>'location_access_denied' THEN RAISE;END IF;END;
 EXECUTE 'SET LOCAL ROLE authenticated';
 IF EXISTS(SELECT 1 FROM tj.org_locations WHERE id=sid) OR EXISTS(SELECT 1 FROM tj.iq_customer_waiting_queue WHERE store_id=sid) OR EXISTS(SELECT 1 FROM tj.crm_deals WHERE organization_id=org AND location_id=sid) THEN RAISE EXCEPTION 'revoked rows visible through authenticated RLS';END IF;
 r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','clock_in','rep_profile_id',prof));
 IF r->>'ok'='true' THEN RAISE EXCEPTION 'revoked staff clocked in';END IF;
 EXECUTE 'RESET ROLE';
 r:=public.tj_runtime_up_administration(payload||jsonb_build_object('action','assign_store','member_id',ownermem,'store_id',sid));
 IF (SELECT count(*) FROM tj_private.up_store_access_events WHERE organization_id=org AND location_id=sid AND member_user_id=actor AND action='revoke')<>1 THEN RAISE EXCEPTION 'revocation audit retry duplicated';END IF;
 IF r->>'ok'<>'true' OR NOT tj_private.aiq_store_allows(org,sid) OR (SELECT count(*) FROM tj.org_location_members WHERE location_id=sid AND user_id=actor)<>1 OR EXISTS(SELECT 1 FROM tj.org_location_members WHERE location_id=sid AND user_id=actor AND (revoked_at IS NOT NULL OR revoked_by IS NOT NULL)) THEN RAISE EXCEPTION 'restore failed: %',r;END IF;

 PERFORM set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);r:=public.tj_runtime_up_rotation(payload||jsonb_build_object('action','recalc'));IF r->>'ok'='true' THEN RAISE EXCEPTION 'unmapped identity allowed';END IF;
END $$;
SELECT jsonb_build_object('passed',true,'persisted_fixture_rows',0,'tests','UP regression; store revoke/retry/restore; retained history; other-store access; primary/context fallback; authenticated location, UP and CRM RLS; blocked revoked-store clock-in; explicit CRM source store') verification;

